// Every mean, median, mode, class mark, cumulative frequency and working-table cell on the slides, in the notes
// and in the figures is computed in stat.mjs (exact BigInt rationals) and asserted here; the build stops on a mismatch.
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, table, flow, plot, build, chapterTests, r } from './lib.mjs';
